//! Navide's agent-CLI runtime, organised around a CLI's lifecycle: launch,
//! session (PTY), observe (records → usage, activity, turns) and resume.
//! See DESIGN.md. A CLI is one declaration under `src/vendors/`.
pub mod decl;
pub mod expr;
pub mod launch;
pub mod observe;
pub mod proto;
pub mod resume;
#[cfg(unix)]
pub mod session;
pub mod time;
pub mod wire;

mod blake2b;
mod md5;

/// Every declared CLI (generated by build.rs from `src/vendors/*.rs`).
pub mod vendors {
    #[allow(unused_imports)]
    use crate::decl::*;
    include!(concat!(env!("OUT_DIR"), "/vendors.rs"));
}

pub fn cli(key: &str) -> Option<&'static decl::Cli> {
    vendors::ALL.iter().copied().find(|c| c.key == key)
}
